:root {
  --bg-parchment: #f0e6cc;
  --bg-card: #fdf6e8;
  --accent-brass: #b5852a;
  --accent-gold: #d4a843;
  --accent-dark: #2c1f0e;
  --text-primary: #2c1f0e;
  --text-secondary: #6b4c1e;
  --text-muted: #9a7a4a;
  --border-main: #c9a96e;
  --ring-outer: #b5852a;
  --ring-mid: #d4a843;
  --ring-center: #fdf6e8;
  --status-critical: #c0392b;
  --status-warn: #d4830a;
  --status-ok: #2e7d32;
  --footer-bg: #2c1f0e;
  --footer-text: #f0e6cc;
  --badge-bg: #b5852a;
  --badge-text: #fdf6e8;
}

.clock-ticket {
  width: 460px;
  background-color: var(--bg-card);
  border: 2px solid var(--border-main);
  border-radius: 8px;
  overflow: hidden;
  font-size: 12px;
  color: var(--text-primary);
}

.ticket-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background-color: var(--bg-parchment);
  border-bottom: 2px solid var(--border-main);
  padding: 8px 12px;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 8px;
}

.shop-icon {
  font-size: 24px;
  line-height: 1;
}

.shop-name {
  font-size: 15px;
  font-weight: 700;
  color: var(--accent-dark);
  margin: 0;
  line-height: 1.2;
}

.shop-subtitle {
  font-size: 10px;
  color: var(--text-muted);
  margin: 0;
  font-style: italic;
}

.ticket-badge {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}

.badge-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 1.2px;
  color: var(--badge-text);
  background-color: var(--badge-bg);
  padding: 2px 5px;
  border-radius: 3px;
}

.badge-num {
  font-size: 13px;
  font-weight: 700;
  color: var(--accent-brass);
}

.ticket-body {
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.clock-details {
  display: flex;
  gap: 12px;
  align-items: center;
}

.clock-face {
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
}

.clock-ring {
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
}

.outer-ring {
  width: 68px;
  height: 68px;
  background-color: var(--ring-outer);
  border: 3px solid var(--accent-dark);
}

.mid-ring {
  width: 52px;
  height: 52px;
  background-color: var(--ring-mid);
  border: 2px solid var(--bg-parchment);
}

.clock-center {
  width: 36px;
  height: 36px;
  background-color: var(--ring-center);
  border-radius: 50%;
  border: 2px solid var(--accent-dark);
  display: flex;
  align-items: center;
  justify-content: center;
}

.clock-emoji {
  font-size: 18px;
  line-height: 1;
}

.clock-label {
  font-size: 9px;
  font-style: italic;
  color: var(--text-muted);
}

.detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px 12px;
  flex: 1;
}

.detail-item {
  display: flex;
  flex-direction: column;
  gap: 1px;
  border-bottom: 1px solid var(--border-main);
  padding-bottom: 3px;
}

.detail-key {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.7px;
  color: var(--text-muted);
  text-transform: uppercase;
}

.detail-val {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-primary);
}

.repair-section {
  border: 1px solid var(--border-main);
  border-radius: 5px;
  padding: 6px 9px;
  background-color: var(--bg-parchment);
}

.section-title {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--text-secondary);
  margin: 0 0 6px 0;
}

.repair-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.repair-item {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 11px;
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

.status-critical .status-dot {
  background-color: var(--status-critical);
}

.status-warn .status-dot {
  background-color: var(--status-warn);
}

.status-ok .status-dot {
  background-color: var(--status-ok);
}

.repair-desc {
  flex: 1;
  color: var(--text-primary);
}

.repair-cost {
  font-weight: 700;
  color: var(--accent-brass);
}

.ticket-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background-color: var(--footer-bg);
  padding: 8px 12px;
  border-top: 2px solid var(--accent-brass);
}

.footer-col {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.footer-col--mid {
  align-items: center;
}

.footer-col--right {
  align-items: flex-end;
}

.foot-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.9px;
  text-transform: uppercase;
  color: var(--accent-gold);
}

.foot-val {
  font-size: 11px;
  font-weight: 600;
  color: var(--footer-text);
}

.foot-total {
  font-size: 17px;
  font-weight: 700;
  color: var(--accent-gold);
  line-height: 1;
}
